{"id": "5296020f-448c-4c7c-b103-36a129605031", "role": "user", "content": [{"id": "tooluse_KeaYPnLd05UUXfnPqo1k1A", "content": [{"text": "Invalid mitigation plan schema: /pre_validate/2/tool_name: must be equal to one of the allowed values. Schema: {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AWS Mitigation Plan Schema",
  "type": "object",
  "required": [
    "apply"
  ],
  "properties": {
    "context": {
      "type": "object",
      "description": "Resource capacity context",
      "properties": {
        "resources": {
          "type": "object",
          "description": "Map of resource ARNs to their capacity information",
          "patternProperties": {
            "^arn:aws:.*": {
              "type": "object",
              "description": "Resource capacity fields",
              "properties": {
                "MinSize": {
                  "type": "integer"
                },
                "MaxSize": {
                  "type": "integer"
                },
                "DesiredCapacity": {
                  "type": "integer"
                },
                "DesiredCount": {
                  "type": "integer"
                },
                "RunningCount": {
                  "type": "integer"
                },
                "AllocatedProvisionedConcurrentExecutions": {
                  "type": "integer"
                },
                "ReadCapacityUnits": {
                  "type": "integer"
                },
                "WriteCapacityUnits": {
                  "type": "integer"
                }
              }
            }
          }
        }
      }
    },
    "prepare": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/tool_call"
      }
    },
    "pre_validate": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/tool_call"
      }
    },
    "apply": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/tool_call"
      }
    },
    "post_validate": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/tool_call"
      }
    },
    "rollback": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/tool_call"
      }
    }
  },
  "definitions": {
    "tool_call": {
      "type": "object",
      "required": [
        "tool_name",
        "input_params",
        "purpose",
        "instruction"
      ],
      "properties": {
        "tool_name": {
          "enum": [
            "use_aws",
            "use_pipeline"
          ]
        },
        "input_params": {
          "type": "object"
        },
        "purpose": {
          "type": "string",
          "description": "Natural language explanation of what this step accomplishes in the mitigation plan"
        },
        "instruction": {
          "type": "string",
          "description": "Specific instructions for the plan executor on what values to capture, verify, or actions to take"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "tool_name": {
                "const": "use_aws"
              }
            }
          },
          "then": {
            "properties": {
              "input_params": {
                "$ref": "#/definitions/aws_params"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "tool_name": {
                "const": "use_pipeline"
              }
            }
          },
          "then": {
            "properties": {
              "input_params": {
                "$ref": "#/definitions/pipeline_params"
              }
            }
          }
        }
      ]
    },
    "aws_params": {
      "type": "object",
      "required": [
        "service_name",
        "operation_name",
        "region"
      ],
      "properties": {
        "service_name": {
          "type": "string",
          "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
          "description": "AWS service name in kababcase (boto3 convention)"
        },
        "operation_name": {
          "type": "string",
          "pattern": "^[a-z0-9]+(_[a-z0-9]+)*$",
          "description": "AWS operation name in snakecase (boto3 convention)"
        },
        "region": {
          "type": "string"
        },
        "parameters": {
          "type": "object"
        }
      }
    },
    "pipeline_params": {
      "type": "object",
      "required": [
        "platform",
        "pipeline_identifier",
        "operation"
      ],
      "properties": {
        "platform": {
          "enum": [
            "GitHub",
            "GitLab"
          ],
          "description": "CI/CD platform type"
        },
        "pipeline_identifier": {
          "type": "string",
          "description": "Pipeline identifier (URL or JSON string)"
        },
        "operation": {
          "enum": [
            "rollback_deployment",
            "identify_rollback_target",
            "pre_validate_rollback_target"
          ],
          "description": "Pipeline operation to execute: identify_rollback_target when rollback target is unknown (finds good version before issue_start_time); pre_validate_rollback_target for safety validation of the targeted rollback version; rollback_deployment to execute the actual rollback"
        },
        "parameters": {
          "type": "object"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "operation": {
                "const": "identify_rollback_target"
              }
            }
          },
          "then": {
            "properties": {
              "parameters": {
                "type": "object",
                "required": [
                  "source_deployment"
                ],
                "properties": {
                  "source_deployment": {
                    "$ref": "#/definitions/deployment"
                  },
                  "issue_start_time": {
                    "type": "string"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "pre_validate_rollback_target"
              }
            }
          },
          "then": {
            "properties": {
              "parameters": {
                "type": "object",
                "required": [
                  "target_deployment"
                ],
                "properties": {
                  "target_deployment": {
                    "$ref": "#/definitions/deployment"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "rollback_deployment"
              }
            }
          },
          "then": {
            "properties": {
              "parameters": {
                "type": "object",
                "required": [
                  "source_deployment",
                  "target_deployment"
                ],
                "properties": {
                  "source_deployment": {
                    "$ref": "#/definitions/deployment"
                  },
                  "target_deployment": {
                    "$ref": "#/definitions/deployment"
                  }
                }
              }
            }
          }
        }
      ]
    },
    "deployment": {
      "type": "object",
      "required": [
        "workflow_name",
        "workflow_run_id",
        "head_commit",
        "full_repo_id"
      ],
      "properties": {
        "workflow_name": {
          "type": "string"
        },
        "workflow_run_id": {
          "type": "string"
        },
        "head_commit": {
          "type": "string"
        },
        "full_repo_id": {
          "type": "string"
        }
      }
    }
  }
}"}], "status": "error", "type": "tool_result"}], "user_reference": null}
